import fs from 'fs';
import path from 'path';
import axios from 'axios';
import { Command } from 'commander';
import { getPluginDir } from '../utils/config.js';

export function registerPlugin(program: Command) {
  const plugin = program.command('plugin').description('Manage gitcli plugins');

  plugin
    .command('install <url>')
    .description('Install plugin from remote JS URL')
    .action(async url => {
      const dir = getPluginDir();
      const fileName = path.basename(url).replace(/\?.*$/, '') || 'plugin.js';
      const target = path.join(dir, fileName);
      const res = await axios.get(url);
      fs.writeFileSync(target, res.data);
      console.log('Installed plugin to', target);
    });

  plugin
    .command('list')
    .description('List installed plugins')
    .action(() => {
      const dir = getPluginDir();
      const files = fs.readdirSync(dir).filter(f => f.endsWith('.js') || f.endsWith('.mjs'));
      console.log('Plugins:', files.join(', ') || 'none');
    });
}
